from typing import Optional
import pymorphy3


_analyzer = pymorphy3.MorphAnalyzer()


def lemmatize(word: str, lang: str) -> Optional[str]:
    if not word:
        return None
    if not lang:
        return None
    if lang != 'ru':
        return None
    parsed = _analyzer.parse(word)
    if parsed:
        # Prefer infinitive (INFN) if available
        for p in parsed:
            if p.tag.POS == 'INFN':
                return p.normal_form
        return parsed[0].normal_form
    return word
