def test_word_search_happy() -> None:
    corpus = {"1": "мирный мир", "2": "мир"}
    engine = SearchEngine(corpus)
    results = engine.word_search("мир")
    assert results is not None
    assert len(results) == 2
    # "мирный мир" -> whole word "мир" at position 7 (after space)
    # "мир" -> whole word at position 0
    assert results[0].text_id == "1"
    assert results[0].positions == [7]
    assert results[1].text_id == "2"
    assert results[1].positions == [0]


